package io.knowledgebrain.brainquery;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;
class BrainNetworkStorageIntegrationTest {
 static UUID id(){var u=UUID.randomUUID();return new UUID((u.getMostSignificantBits()&~0xf000L)|0x7000L,u.getLeastSignificantBits());}
 BrainProjectionStore.Document doc(String kind,UUID id,UUID space,long seq,boolean visible,String title,List<BrainProjection.Ref> refs,UUID subject){return new BrainProjectionStore.Document(kind,id,space,1,seq,visible,visible?title:"",visible?"Network body fixture":"",refs,subject);}
 @Test @EnabledIfEnvironmentVariable(named="BRAIN_TEST_GRAPH_HOST",matches=".+") void typedGraphPersistsCanonicalVersionAndRoleEdgesWhileHidingRetiredEndpoints()throws Exception{
  String host=System.getenv("BRAIN_TEST_GRAPH_HOST"),trust="/graph-trust/truststore.p12",password=Files.readString(Path.of("/graph-projector/password")).strip();
  try(var admin=NoteGraphStore.open(host,Files.readString(Path.of("/graph-admin/username")).strip(),Files.readString(Path.of("/graph-admin/password")).strip(),trust,password)){BrainGraphStore.initialize(admin);}
  UUID space=id(),concept=id(),claim=id(),note=id();var refs=List.of(new BrainProjection.Ref(claim,"SUBJECT","CONCEPT",concept),new BrainProjection.Ref(claim,"PREDICATE","CONCEPT",concept),new BrainProjection.Ref(claim,"OBJECT","CONCEPT",concept));
  try(var graph=BrainNetworkConfiguration.graph(host,"/graph-projector",trust)){
   graph.apply(doc("CLAIM",claim,space,1,true,"Triple",refs,concept));assertEquals(1,graph.read(space,10).nodes().size());assertTrue(graph.read(space,10).edges().isEmpty());
   graph.applyBatch(List.of(doc("CONCEPT",concept,space,2,true,"Concept",List.of(),null),doc("NOTE",note,space,3,true,"Note",List.of(new BrainProjection.Ref(id(),"NOTE_CONCEPT","CONCEPT",concept)),null)));
   assertEquals(3,graph.read(space,10).nodes().size());assertEquals(4,graph.read(space,10).edges().size());assertEquals(Set.of("SUBJECT","PREDICATE","OBJECT","NOTE_CONCEPT"),new HashSet<>(graph.read(space,10).edges().stream().map(BrainGraphStore.Edge::role).toList()));
   var renamed=doc("CLAIM",claim,space,4,true,"Updated triple",refs,concept);graph.apply(renamed);graph.apply(renamed);graph.apply(doc("CLAIM",claim,space,1,true,"Old triple",refs,concept));assertEquals(1,graph.read(space,10).nodes().stream().filter(n->n.kind().equals("CLAIM")).findFirst().orElseThrow().version());
   var partial=id();assertThrows(BrainProjectionStore.Conflict.class,()->graph.applyBatch(List.of(doc("NOTE",partial,space,8,true,"Partial",List.of(),null),doc("CLAIM",claim,space,4,true,"Conflict",refs,concept))));assertTrue(graph.read(space,10).nodes().stream().noneMatch(n->n.id().equals(partial)));assertThrows(BrainProjectionStore.Conflict.class,()->graph.apply(doc("NOTE",note,id(),8,true,"Moved",List.of(),null)));
   graph.apply(doc("CONCEPT",concept,space,5,false,"",List.of(),null));assertTrue(graph.read(space,10).edges().isEmpty());assertTrue(graph.read(id(),10).nodes().isEmpty());
  }
  try(var reopened=BrainNetworkConfiguration.graph(host,"/graph-projector",trust)){assertEquals(2,reopened.read(space,10).nodes().size());assertTrue(reopened.read(space,10).edges().isEmpty());}
 }
 @Test @EnabledIfEnvironmentVariable(named="BRAIN_TEST_SEARCH_ORIGIN",matches=".+") void fixedTlsIndexEnforcesRoleScopeAndWorkSequenceWithoutRewritingCanonicalVersion()throws Exception{
  var writer=new NoteSearchClient(System.getenv("BRAIN_TEST_SEARCH_ORIGIN"),Path.of("/search-projector"));var reader=new NoteSearchClient(System.getenv("BRAIN_TEST_SEARCH_ORIGIN"),Path.of("/search-reader"));UUID space=id(),claim=id(),subject=id();var original=doc("CLAIM",claim,space,3,true,"NetworkSequenceFixture",List.of(),subject);writer.applyBrainBatch(List.of(original));writer.applyBrainBatch(List.of(original));writer.applyBrainBatch(List.of(doc("CLAIM",claim,space,2,true,"Old",List.of(),subject)));assertThrows(NoteSearchClient.Conflict.class,()->writer.applyBrainBatch(List.of(doc("CLAIM",claim,space,3,true,"Conflicting",List.of(),subject))));
  for(int i=0;i<30&&reader.searchBrain(space,"NetworkSequenceFixture",0,20,"CLAIM").path("total").path("value").asLong()!=1;i++)Thread.sleep(200);
  var hits=reader.searchBrain(space,"NetworkSequenceFixture",0,20,"CLAIM");assertEquals(1,hits.path("total").path("value").asLong());assertEquals(1,hits.path("hits").get(0).path("_source").path("canonicalVersion").asLong());assertEquals(0,reader.searchBrain(id(),"NetworkSequenceFixture",0,20,null).path("total").path("value").asLong());
  assertThrows(NoteSearchClient.Unavailable.class,()->reader.applyBrain(doc("NOTE",id(),space,1,true,"Denied",List.of(),null)));assertThrows(NoteSearchClient.Unavailable.class,()->writer.searchBrain(space,"Denied",0,20,null));writer.applyBrain(doc("CLAIM",claim,space,4,false,"",List.of(),subject));writer.applyBrain(original);
  for(int i=0;i<30&&reader.searchBrain(space,"NetworkSequenceFixture",0,20,null).path("total").path("value").asLong()!=0;i++)Thread.sleep(200);assertEquals(0,reader.searchBrain(space,"NetworkSequenceFixture",0,20,null).path("total").path("value").asLong());
 }
 @Test @EnabledIfEnvironmentVariable(named="BRAIN_TEST_GRAPH_HOST",matches=".+") void typedRecordEdgesPersistAndArchiveRemovesRecordWithoutConceptMutation()throws Exception{String host=System.getenv("BRAIN_TEST_GRAPH_HOST"),trust="/graph-trust/truststore.p12";UUID space=id(),concept=id();try(var graph=BrainNetworkConfiguration.graph(host,"/graph-projector",trust)){graph.apply(doc("CONCEPT",concept,space,1,true,"Related",List.of(),null));for(var kind:List.of("BOOKMARK","QUESTION","DECISION")){var record=id();graph.apply(doc(kind,record,space,2,true,kind,List.of(new BrainProjection.Ref(id(),"RECORD_CONCEPT","CONCEPT",concept)),null));assertTrue(graph.read(space,20).edges().stream().anyMatch(e->e.source().equals(kind+":"+record)&&e.role().equals("RECORD_CONCEPT")));graph.apply(doc(kind,record,space,3,false,"",List.of(),null));assertTrue(graph.read(space,20).nodes().stream().noneMatch(n->n.id().equals(record)));}assertEquals(1,graph.read(space,20).nodes().size());}}
 @Test @EnabledIfEnvironmentVariable(named="BRAIN_TEST_SEARCH_ORIGIN",matches=".+") void allThreeRecordTypesAreIsolatedAndSearchBodyOnlyText()throws Exception{var writer=new NoteSearchClient(System.getenv("BRAIN_TEST_SEARCH_ORIGIN"),Path.of("/search-projector"));var reader=new NoteSearchClient(System.getenv("BRAIN_TEST_SEARCH_ORIGIN"),Path.of("/search-reader"));var space=id();for(var kind:List.of("BOOKMARK","QUESTION","DECISION")){var record=id();writer.applyBrain(doc(kind,record,space,1,true,"Record",List.of(),null));for(int i=0;i<30&&reader.searchBrain(space,"Network body fixture",0,20,kind).path("total").path("value").asLong()!=1;i++)Thread.sleep(200);assertEquals(1,reader.searchBrain(space,"Network body fixture",0,20,kind).path("total").path("value").asLong());assertEquals(0,reader.searchBrain(id(),"Network body fixture",0,20,kind).path("total").path("value").asLong());writer.applyBrain(doc(kind,record,space,2,false,"",List.of(),null));}}
}
